const dayDates = [
  "2026-08-29",
  "2026-08-30",
  "2026-08-31",
  "2026-09-01",
  "2026-09-02",
  "2026-09-03",
  "2026-09-04",
  "2026-09-05",
];

const effortMilesFor = (day) =>
  Number(
    (
      day.distanceMiles + day.gainFeet / 2_000 + day.lossFeet / 4_000
    ).toFixed(1),
  );

const timeEstimateFor = (day) => {
  const speed = day.packMode === "day-pack-supported" ? 2.1 : 1.85;
  const moving = effortMilesFor(day) / speed;
  const quarterHour = (hours) => Math.round(hours * 4) / 4;
  return {
    movingHours: moving,
    lowHours: quarterHour(moving * 1.12),
    highHours: quarterHour(moving * 1.35),
  };
};

const allTimeEstimates = terrain.days.map(timeEstimateFor);
const terrainDaySummary = terrain.days.map((day) => ({
  ...day,
  effortMiles: effortMilesFor(day),
  timeEstimate: timeEstimateFor(day),
}));
const effortOrder = [...terrainDaySummary]
  .sort((first, second) => second.effortMiles - first.effortMiles)
  .map((day) => day.day);

