const terrainLoadFor = (day) => {
  const ascentPerMile = Math.round(day.gainFeet / day.distanceMiles);
  const descentPerMile = Math.round(day.lossFeet / day.distanceMiles);
  return {
    netFeet: day.endElevationFeet - day.startElevationFeet,
    totalVerticalFeet: day.gainFeet + day.lossFeet,
    ascentPerMile,
    descentPerMile,
    effortMiles: effortMilesFor(day),
    kneeLoad:
      day.lossFeet >= 1_400 || descentPerMile >= 300
        ? "very-high"
        : day.lossFeet >= 900 || descentPerMile >= 225
          ? "high"
          : day.lossFeet >= 600
            ? "moderate"
            : "low",
    effortRank: effortOrder.indexOf(day.day) + 1,
  };
};

export const primaryItinerary = terrainDaySummary.map((day) => {
  const context = planningContextByDay[day.day] ?? {};
  return {
    day: day.day,
    date: dayDates[day.day - 1],
    from: day.from,
    to: day.to,
    distance: day.distanceMiles,
    routeMileStart: day.startRouteMile,
    routeMileEnd: day.endRouteMile,
    pctMileStart: day.startPctMile,
    pctMileEnd: day.endPctMile,
    coordinates: {
      latitude: day.fieldEndCoordinates[1],
      longitude: day.fieldEndCoordinates[0],
    },
    trailAccessCoordinates: {
      latitude: day.trailEndCoordinates[1],
      longitude: day.trailEndCoordinates[0],
    },
    fieldToTrailOffsetFeet: day.fieldToTrailOffsetFeet,
    water: context.water ?? "Current water verification required",
    note: context.note ?? "Current field verification required.",
    stopType: day.stopType,
    campStatus: day.campStatus,
    elevation: {
      start: day.startElevationFeet,
      end: day.endElevationFeet,
      gain: day.gainFeet,
      loss: day.lossFeet,
      high: day.highPointFeet,
      low: day.lowPointFeet,
    },
    terrainLoad: terrainLoadFor(day),
    packMode: day.packMode,
    timeEstimate: day.timeEstimate,
  };
});

